  "Gõ /history hoặc /history <số từ 1 đến 50>.": "Type /history or /history <a number from 1 to 50>.",
  "Gõ /react rồi một cảm xúc: {0}.": "Type /react, then a reaction: {0}.",
  "Gõ /reply #3.1 rồi tin nhắn. /history cho xem số của từng tin.": "Type /reply #3.1, then your message. /history shows each message's number.",
  'Skill': 'Skill',
  'Dùng số tiền từ 0.001 đến {0} USD.': 'Use an amount from 0.001 to {0} USD.',
