  // The Demo answer and report line before COD-293, still in chats saved earlier.
  'Mình là Tí demo nên chưa đọc tệp hay gọi model thật. Chọn OpenAI, Anthropic hoặc harness trên máy (Claude Code, Codex) trong thiết lập Tí để trò chuyện và làm việc thật nhé.': 'I\'m a demo orglet, so I can\'t read files or call a real model yet. Pick OpenAI, Anthropic or a local harness (Claude Code, Codex) in the orglet settings to chat and work for real.',
  'Mình là Tí demo nên chưa đọc tệp hay gọi model thật. Bấm Kết nối model dưới khung chat để chọn một model thật, rồi mình trò chuyện và làm việc thật nhé.': 'I\'m a demo orglet, so I can\'t read files or call a real model yet. Choose Connect a model under the message box to pick a real one, then I can chat and work for real.',
