  'Nguồn đã bị thu hồi trước khi lưu câu trả lời.': 'A source was revoked before the reply was saved.',
  'Kênh có checklist bắt buộc cần báo cáo đầy đủ, không phải tin nhắn.': 'A channel with a required checklist needs a full report, not a chat message.',
  'Trả lời': 'Reply',
  '{0} đã trả lời; harness ước tính ${1} theo gói hoặc tài khoản của nó. Khoản này tính vào giới hạn mỗi task của chat này, không trừ vào ngân sách tháng.': '{0} replied; the harness estimates ${1} on its own plan or account. That counts toward this chat’s limit per task, not the monthly budget.',
  '{0} dừng ở giới hạn; harness ước tính ${1} theo gói hoặc tài khoản của nó. Khoản này tính vào giới hạn mỗi task của chat này, không trừ vào ngân sách tháng.': '{0} stopped at the limit; the harness estimates ${1} on its own plan or account. That counts toward this chat’s limit per task, not the monthly budget.',
