  '{0} dừng vì chạm giới hạn mỗi task của chat này ({1}). Nâng Giới hạn mỗi task trong Thiết lập kênh → Giới hạn & ca, rồi thử lại.': '{0} stopped at this chat’s limit per task ({1}). Raise Limit per task in Channel settings → Limits & shifts, then retry.',
  '{0} dừng vì chạm giới hạn mỗi task của chat này ({1}). Nâng Giới hạn mỗi task trong Thiết lập Tí, rồi thử lại.': '{0} stopped at this chat’s limit per task ({1}). Raise Limit per task in Orglet settings, then retry.',
