  'Tìm hiểu chủ đề này': 'Look into a topic',
  'Tìm hiểu chủ đề sau và tóm tắt những gì đã biết, kèm nguồn cho từng ý: ': 'Look into the following and summarize what is already known, with a source for each point: ',
  'Kiểm chứng một khẳng định': 'Check a claim',
  'Kiểm chứng khẳng định sau. Nói rõ nó đúng, sai hay chưa đủ căn cứ, và dựa vào đâu: ': 'Check the claim below. Say whether it holds, does not hold, or has too little behind it, and on what basis: ',
  'Chỉ ra điều đáng chú ý trong số liệu': 'Point out what stands out in the numbers',
  'Xem số liệu đã đính kèm và chỉ ra điều đáng chú ý: xu hướng, giá trị bất thường, và điều gì chưa đủ dữ liệu để kết luận.': 'Look at the attached numbers and point out what stands out: trends, odd values, and what there is not enough data to conclude.',
  'Trả lời một câu hỏi bằng số liệu': 'Answer a question with the numbers',
  'Dùng số liệu để trả lời câu hỏi sau, nêu rõ cách tính và giới hạn của câu trả lời: ': 'Use the numbers to answer the question below, and say how you worked it out and where the answer stops holding: ',
  'Review các tệp đã đính kèm. Nêu vấn đề kèm bằng chứng, nói rõ đã kiểm tra tới đâu và còn giới hạn gì. Không thực thi code.': 'Review the attached files. Raise problems with evidence, say how far you checked and what the limits are. Do not run code.',
  'Cho ý kiến ngược lại': 'Argue the other side',
  'Đọc phần sau và phản biện: chỗ nào yếu, chỗ nào mình đang cho là đúng mà chưa có căn cứ: ': 'Read the following and push back: what is weak, and what am I treating as true without grounds: ',
  'Soát rủi ro': 'Look for risks',
  'Soát phần sau và liệt kê rủi ro thật sự, xếp theo mức nghiêm trọng, kèm lý do cho từng cái: ': 'Go through the following and list the real risks, worst first, with a reason for each: ',
  'Viết bản nháp đầu tiên': 'Write a first draft',
  'Viết bản nháp đầu tiên cho: ': 'Write a first draft of: ',
  'Rút gọn cho dễ đọc': 'Tighten it up',
  'Rút gọn đoạn sau, giữ nguyên ý và bỏ phần thừa: ': 'Tighten the following: keep the meaning, drop what is not carrying weight: ',
  'Giải thích đoạn code này': 'Explain this code',
  'Giải thích đoạn code đã đính kèm làm gì, và chỗ nào dễ hiểu sai: ': 'Explain what the attached code does, and where it is easy to misread: ',
  'Bàn cách làm': 'Talk through the approach',
  'Mình đang định làm thế này. Nói xem cách nào gọn hơn và cách của mình hỏng ở đâu: ': 'Here is what I am planning to do. Tell me what would be simpler, and where mine breaks: ',
  'Soạn câu trả lời': 'Draft a reply',
  'Soạn câu trả lời cho tin nhắn sau. Ngắn, thẳng, không hứa điều mình chưa chắc: ': 'Draft a reply to the message below. Short, direct, and no promises we are not sure of: ',
  'Chia việc này thành các bước': 'Break this into steps',
  'Chia việc thành các bước': 'Break the work into steps',
  'Chia việc sau thành các bước làm được, nói rõ bước nào chặn bước nào: ': 'Break the following into steps someone can act on, and say which step blocks which: ',
  'Viết thông báo ngắn': 'Write a short announcement',
  'Viết thông báo ngắn cho: ': 'Write a short announcement for: ',
  'Kiểm tra các con số': 'Check the numbers',
  'Kiểm tra các con số trong tệp đã đính kèm: chỗ nào không khớp, chỗ nào thiếu.': 'Check the numbers in the attached file: what does not add up, and what is missing.',
  'Tóm tắt tài liệu đã đính kèm': 'Summarize the attached documents',
  'Đọc các tài liệu đã đính kèm, tóm tắt những điểm chính và chỉ rõ phần còn thiếu bằng chứng.': 'Read the attached documents, summarize the main points, and say plainly where the evidence is thin.',
  'Hỏi xem giúp được gì': 'Ask what they can help with',
  'Với những gì bạn được giao, bạn giúp mình được những việc gì? Hỏi lại nếu cần biết thêm.': 'Given what you were set up to do, what can you help me with? Ask me back if you need more.',
  'Giao việc này cho cả kênh': 'Give this to the whole channel',
