  'Thư mục làm việc {0} của lịch không còn hoặc đã bị thay thế, nên lịch chưa chạy. Chọn lại thư mục trong lịch rồi lưu.': 'The schedule’s working folder {0} is gone or was replaced, so the schedule did not run. Choose the folder again in the schedule and save it.',
  'Thay đổi của lần chạy trước vẫn chờ bạn xem. Mở lần chạy đó, áp dụng hoặc bỏ thay đổi rồi chạy lại.': 'The last run’s changes still wait for your review. Open that run, apply or discard them, then run it again.',
  'Chưa dùng được thư mục vì lịch này chưa có thư mục làm việc. Chọn một thư mục ở Lịch chạy → Sửa lịch → Thư mục làm việc, rồi lưu lịch.': 'Could not use a folder: this schedule has no working folder. Choose one in Schedules → Edit schedule → Working folder, then save the schedule.',
  'Chưa sửa được tệp vì thư mục làm việc của lịch chỉ cho đọc. Đổi thành “Đọc và sửa file” ở Lịch chạy → Sửa lịch → Thư mục làm việc, rồi lưu lịch.': 'Could not edit files: the schedule’s working folder is read only. Set Schedules → Edit schedule → Working folder to “Read and edit files”, then save the schedule.',
  'Chưa chạy được lệnh vì thư mục làm việc của lịch chưa cho chạy lệnh. Đổi thành “Đọc, sửa file và chạy lệnh” ở Lịch chạy → Sửa lịch → Thư mục làm việc, rồi lưu lịch.': 'Could not run commands: the schedule’s working folder does not allow them. Set Schedules → Edit schedule → Working folder to “Read, edit files and run commands”, then save the schedule.',
