  'Lịch chỉ đọc trang, không bấm hay gửi gì. Trang trên máy này hoặc mạng nội bộ cần có trong danh sách; hồ sơ đã đăng nhập chỉ mở trang được phép.': 'A schedule only reads pages; it never clicks or sends anything. Pages on this computer or your local network need to be on the list, and a signed-in profile opens allowed sites only.',
