  'Chat đã đổi hồ sơ trình duyệt; lượt chạy này dừng dùng trình duyệt. Tin nhắn sau sẽ dùng hồ sơ mới.': 'The chat switched browser profile, so this run stopped using the browser. The next message uses the new profile.',
