  'Không mở địa chỉ có kèm tên đăng nhập hoặc mật khẩu.': 'Addresses with a user name or password are never opened.',
  'Trình duyệt của Orglet chỉ mở trang http và https. Trang cài đặt, tiện ích, tệp trên máy và các loại địa chỉ khác không bao giờ mở được.': 'Orglet’s browser opens http and https pages only. Settings, extension and file pages and other kinds of address never open.',
  'Trang này bị chặn trong danh sách trang của chat.': 'This site is blocked on the chat’s site list.',
  'Trang trên máy này hoặc trong mạng nội bộ chỉ mở được khi bạn thêm đúng địa chỉ đó (ví dụ localhost:3000) vào danh sách trang được phép của chat.': 'A page on this computer or your local network opens only when you add that exact address (such as localhost:3000) to the chat’s allowed sites.',
  'Hồ sơ đã đăng nhập chỉ mở các trang có trong danh sách trang được phép của chat.': 'A signed-in profile opens only the sites on the chat’s allowed list.',
  // Acting on pages (COD-261, phase 2).
  'Đọc và thao tác': 'Read and act',
  'Bấm, gõ và chọn trên trang; hỏi bạn trước khi gửi, trả tiền hay xóa.': 'Clicks, types and chooses on pages; asks you before sending, paying or deleting.',
  'Thao tác trên trang cần quyền đọc trang.': 'Acting on pages needs reading pages too.',
  'Lịch chỉ được đọc trang, không được thao tác trên trang. Chọn "Đọc trang" cho trình duyệt.': 'A schedule may only read pages, never act on them. Set the browser to "Read pages".',
  'Mã phần tử không hợp lệ.': 'Invalid element ref.',
  'Mã phần tử này không còn trên trang. Đọc lại trang bằng browser_snapshot rồi dùng mã mới.': 'This element ref is no longer on the page. Read the page again with browser_snapshot and use a new ref.',
  'Phần tử này đã đổi hoặc không còn trên trang nên không làm gì. Đọc lại trang bằng browser_snapshot rồi dùng mã mới.': 'This element changed or is gone, so nothing was done. Read the page again with browser_snapshot and use a new ref.',
  'Trang đã chuyển sang địa chỉ khác trước bước này nên không làm gì. Đọc lại trang bằng browser_snapshot.': 'The page moved to another address before this step, so nothing was done. Read the page again with browser_snapshot.',
  'Bước này cần người dùng cho phép, mà kênh và lịch không hỏi được. Nhờ người dùng tự làm, hoặc làm trong chat riêng với Tí này.': 'This step needs the person’s permission, and group chats, channels and schedules cannot ask. Ask the person to do it, or to do it in a chat with this orglet alone.',
  'Người dùng không cho phép bước này. Đừng thử lại bước này trong lượt này.': 'The person did not allow this step. Do not try it again in this turn.',
