  'Các bước sẽ làm': 'Planned steps',
  'Tối đa {0} giây. Orglet đưa cửa sổ lên trước, làm đúng các bước này, rồi trả lại cửa sổ và con trỏ cho bạn. Chạm vào chuột hoặc nhấn Esc là dừng ngay.': 'At most {0} seconds. Orglet brings the window to the front, does exactly these steps, then gives your window and cursor back. Touch the mouse or press Esc to stop it at once.',
  'Đã mượn chuột {0} giây trong “{1}” · bạn cho phép': 'Borrowed the mouse for {0} s in “{1}” · you allowed',
  'Đã mượn chuột {0} giây trong “{1}” · bạn đã dừng': 'Borrowed the mouse for {0} s in “{1}” · you stopped it',
  'Đã mượn chuột {0} giây trong “{1}” · dừng giữa chừng: {2}': 'Borrowed the mouse for {0} s in “{1}” · stopped early: {2}',
  'Đã hỏi để mượn chuột trong “{0}” · bị từ chối': 'Asked to borrow the mouse in “{0}” · declined',
