  'một cửa sổ khác đã lên trước': 'another window came to the front',
  'phần tử không còn nhận thao tác': 'the element stopped taking the input',
  'Windows không cho đưa cửa sổ lên trước': 'Windows did not let Orglet bring the window forward',
  'lần chạy đã dừng': 'the run was stopped',
  'Mượn chuột và bàn phím thật luôn cần người dùng cho phép, mà kênh và lịch không hỏi được. Nhờ người dùng tự làm bước này.': 'Borrowing the real mouse and keyboard always needs the person’s OK, and group chats, channels and schedules cannot ask. Ask the person to do this step themselves.',
  'Bước này làm được trong nền, nên Orglet không mượn chuột và bàn phím thật cho nó.': 'This step can be done in the background, so Orglet does not borrow the real mouse and keyboard for it.',
  'Kế hoạch này cần hơn 10 giây chuột và bàn phím thật. Chia nó thành các lần mượn ngắn hơn.': 'This plan needs the real mouse and keyboard for more than 10 seconds. Split it into shorter borrows.',
  'Cửa sổ đang thu nhỏ. Orglet không tự mở nó ra để mượn chuột; nhờ người dùng mở lại cửa sổ.': 'The window is minimized. Orglet does not restore it to borrow the mouse; ask the person to restore it.',
  'Người dùng đã từ chối hoặc đã dừng một lần mượn chuột trong lượt này, nên Orglet không hỏi mượn lại.': 'The person declined or stopped a borrow in this turn, so Orglet does not ask again.',
  'Orglet đang dùng chuột và bàn phím của bạn · nhấn Esc để dừng': 'Orglet is using your mouse and keyboard · press Esc to stop',
  '{0} đang dùng chuột của bạn · nhấn Esc để dừng': '{0} is using your mouse · press Esc to stop',
  '{0} đang dùng {1}': '{0} is using {1}',
  'Windows đang hiện màn hình khóa hoặc hộp thoại quyền quản trị, nên Orglet không mượn chuột và bàn phím.': 'Windows is showing the lock screen or an administrator prompt, so Orglet does not borrow the mouse and keyboard.',
  'Phần tử này không nằm trên màn hình, nên chuột không tới được.': 'This element is not on the screen, so the mouse cannot reach it.',
  'Một lần mượn chuột khác đang chạy.': 'Another borrow of the mouse is running.',
  'Không làm được trong nền, nên cần chuột và bàn phím thật của bạn': 'It cannot be done in the background, so it needs your real mouse and keyboard',
  'Lần mượn chuột trước chưa rõ kết quả. Không tự chạy lại; cần kiểm tra cửa sổ trước.': 'The earlier borrow has no known result. It does not run again by itself; check the window first.',
