  // COD-344: what an account gives, and usage analytics for a signed-in account.
  'Tài khoản mang lại gì': 'What an account gives you',
  'Miễn phí, một tài khoản CodePawl cho mọi sản phẩm CodePawl.': 'Free, and one CodePawl account for every CodePawl product.',
  'Sắp có: đồng bộ Tí, kênh, cuộc trò chuyện và cài đặt giữa các máy.': 'Coming next: sync your orglets, channels, chats and settings between computers.',
  'Sau này: dùng Orglet trên điện thoại.': 'Later: Orglet on your phone.',
  'Thống kê sử dụng giúp Orglet tốt hơn cho cách bạn dùng.': 'Usage statistics help shape Orglet around how you use it.',
  'Khi đăng nhập, Orglet gửi thống kê sử dụng và báo lỗi, không kèm nội dung chat hay tệp. Tắt được bất cứ lúc nào.': 'Signing in sends usage statistics and error reports, never your chats or files. You can turn this off at any time.',
  'Gửi thống kê sử dụng và báo lỗi, không kèm nội dung chat hay tệp. Tắt được bất cứ lúc nào.': 'Sends usage statistics and error reports, never your chats or files. You can turn this off at any time.',
  'Quyền riêng tư': 'Privacy',
  'Điều khoản': 'Terms',
  'Những gì được gửi': 'What is sent',
  'Được gửi': 'Sent',
  'Phiên bản, hệ điều hành, tính năng đã dùng, loại cuộc trò chuyện, nhà cung cấp và model, kết quả lượt chạy, và lỗi đã bỏ thông tin cá nhân.': 'Version, operating system, features used, kind of chat, provider and model, how runs ended, and errors with personal details removed.',
  'Không bao giờ gửi': 'Never sent',
  'Nội dung chat, prompt, câu trả lời, tên và nội dung tệp, đường dẫn thư mục, tên và hướng dẫn của Tí hay kênh, key, token và email.': 'Chat text, prompts, answers, file names and contents, folder paths, orglet and channel names and instructions, keys, tokens and emails.',
  'Lưu giữ': 'Kept',
  '180 ngày, và bị xóa cùng tài khoản.': 'For 180 days, and deleted with your account.',
  'Thống kê sử dụng và báo lỗi': 'Usage statistics and error reports',
  'Thống kê sử dụng': 'Usage statistics',
  'Sắp có. Hiện chưa có chat hay tệp nào rời khỏi máy này.': 'Coming next. No chat or file leaves this computer yet.',
  // COD-329 phase 3: the sync row in Settings → Account.
  'Đồng bộ đang tắt trên máy này. Bật lên rồi chọn gộp hay thay dữ liệu ở đây.': 'Sync is off on this computer. Turn it on, then choose to merge or replace what is here.',
  // GH-484: versions two computers wrote while apart.
  'Sửa trên hai máy': 'Changed on two computers',
  '{0} mục được sửa trên hai máy khi chưa đồng bộ. Orglet đang dùng bản sửa sau; bản kia vẫn còn.': '{0} items were changed on two computers before they synced. Orglet uses the later change; the other is still there.',
