  'Thay bằng tài khoản': 'Replace with account',
  'Thay dữ liệu trên máy này?': 'Replace what is on this computer?',
  'Mọi Tí và cuộc trò chuyện trên máy này bị xóa, kể cả {0} mục "Chỉ trên máy này". Orglet lưu một bản sao cạnh dữ liệu trước khi xóa. Tài khoản không bị xóa gì.': 'Every orglet and chat on this computer is erased, including {0} items marked "Only on this computer". Orglet saves a copy beside your data first. Nothing is deleted from your account.',
  'Mọi Tí và cuộc trò chuyện trên máy này bị xóa. Orglet lưu một bản sao cạnh dữ liệu trước khi xóa. Tài khoản không bị xóa gì.': 'Every orglet and chat on this computer is erased. Orglet saves a copy beside your data first. Nothing is deleted from your account.',
  'Thay thế': 'Replace',
  'Máy này không còn gì phải chọn cho đồng bộ.': 'There is nothing left to choose for sync on this computer.',
  'Không đọc được tài khoản. Kiểm tra kết nối rồi thử lại.': 'Could not read your account. Check your connection and try again.',
  'Máy chủ đồng bộ không nhận phiên đăng nhập này. Đăng xuất rồi đăng nhập lại.': 'The sync server did not accept this sign-in. Sign out and sign in again.',
  'Máy chủ đồng bộ đang gặp lỗi. Thử lại sau.': 'The sync server is having trouble. Try again later.',
  'Tài khoản vừa gửi quá nhiều yêu cầu. Chờ vài phút rồi thử lại.': 'Your account sent too many requests. Wait a few minutes and try again.',
  'Không tạo được bản sao an toàn trước khi thay thế.': 'Could not save a copy before replacing.',
  'Bật đồng bộ': 'Turn on sync',
