  "Thư mục {0}": "Folder {0}",
  "Tùy chọn thư mục {0}": "Options for the folder {0}",
  "Chuyển vào thư mục {0}": "Move to the folder {0}",
  "Chuyển vào thư mục mới": "Move to a new folder",
  "Đưa ra khỏi thư mục": "Take out of the folder",
  "Đóng mọi thư mục": "Close all folders",
  "Bỏ thư mục": "Remove the folder",
  "ví dụ: Khách hàng": "for example: Clients",
  "Các không gian cùng tên thư mục nằm chung một nhóm trên thanh bên trái. Để trống thì không gian đứng riêng.": "Spaces with the same folder name sit in one group on the left rail. Leave it empty and the space stands alone.",
  "Cách dùng: orglet market [--refresh] [--json]\n       orglet market installed [--json]\n       orglet market add <mã> [--json]\n\nLiệt kê marketplace: mã, loại, tên, tác giả và mô tả của từng mục. installed liệt kê\nnhững gì đã thêm từ marketplace và mục nào có bản cập nhật. add thêm bản hiện tại\ncủa một mục: các Tí của nó, cùng kênh hoặc không gian nó mang theo. Không cần tài khoản.\nXuất bản, duyệt và áp dụng bản cập nhật làm trong app, nơi bạn xem nội dung trước.\n\nTùy chọn:\n  --refresh      Tải lại danh mục thay vì dùng bản đã lưu\n  --json         In JSON cho máy đọc": "Usage: orglet market [--refresh] [--json]\n       orglet market installed [--json]\n       orglet market add <id> [--json]\n\nLists the marketplace: each listing\'s id, kind, name, author and summary. installed lists\nwhat was added from the marketplace and which of it has an update. add adds the current\nversion of a listing: its orglets, and the channel or space it carries. No account is needed.\nPublishing, reviewing and applying an update happen in the app, where you see the content first.\n\nOptions:\n  --refresh      Fetch the catalog again instead of using the saved copy\n  --json         Print machine-readable JSON",
  "Gõ installed hoặc add <mã> sau orglet market, hoặc không gõ gì để xem danh mục.": "Type installed or add <id> after orglet market, or nothing to see the catalog.",
  "Chỉ orglet market add nhận một mã.": "Only orglet market add takes an id.",
  "--refresh chỉ dùng khi xem danh mục.": "--refresh is only for the catalog.",
  "Gõ mã của mục như orglet market in ra, ví dụ: orglet market add launch-space": "Type the listing's id as orglet market prints it, for example: orglet market add launch-space",
  "Chưa thêm gì từ marketplace.": "Nothing was added from the marketplace yet.",
  "có bản cập nhật": "update available",
  "Đây là danh mục đã lưu; chưa tải được bản mới.": "This is the saved catalog; a new one could not be fetched.",
  "Đây là danh mục đi kèm app; chưa tải được danh mục trực tuyến.": "This is the catalog that ships with the app; the online catalog could not be fetched.",
  "Còn mục khác; xem tất cả trong app.": "There are more listings; see them all in the app.",
