  "Gõ tên không gian sau --space.": "Type the space's name after --space.",
  "Gõ tên mục sau --category.": "Type the category's name after --category.",
  "--category cần --space <tên không gian>.": "--category needs --space <space name>.",
  "Hai kênh trong không gian trùng tên. Đổi tên một kênh rồi xem trước lại.": "Two channels in the space have the same name. Rename one, then preview again.",
  "Không gian chưa có kênh nào để chia sẻ.": "The space has no channel to share yet.",
  "Gõ tin nhắn đầu tiên, ví dụ: orglet {0} \"Chào cả kênh\" --with Researcher --with Writer": "Type the first message, for example: orglet {0} \"Hello everyone\" --with Researcher --with Writer",
  "Gõ {0} Tí một, Tí hai -- tin nhắn đầu tiên.": "Type {0} Orglet one, Orglet two -- first message.",
  "Gõ /members rồi tên các Tí, cách nhau bằng dấu phẩy.": "Type /members, then orglet names separated by commas.",
  "Tạo kênh với các Tí này (/group là tên cũ)": "Create a channel with these orglets (/group is the older name)",
  "Đổi thành viên của kênh này": "Change this channel's members",
  "Từ tin nhắn sau, kênh gồm: {0}.": "From the next message on, the channel has: {0}.",
  "Cách dùng: orglet chats [--archived] [--space <tên>] [--json]\n\nLiệt kê chat, mới nhất trước: chat chính của Tí và kênh, chat phụ, kênh và lần\nchạy của lịch, mỗi chat có mã ngắn. Dùng mã với --chat trong các lệnh khác.\n\nTùy chọn:\n  --archived     Chỉ liệt kê chat đã lưu trữ\n  --space <tên>  Chỉ liệt kê kênh của không gian này\n  --json         In JSON cho máy đọc": "Usage: orglet chats [--archived] [--space <name>] [--json]\n\nLists chats, newest first: orglets' and channels' main chats, side threads, channels\nand schedule runs, each with a short id. Use the id with --chat in other commands.\n\nOptions:\n  --archived     List only archived chats\n  --space <name> List only the channels of this space\n  --json         Print machine-readable JSON",
  "Cách dùng: orglet members --chat <mã> --with <tên> [--with <tên>] [--json]\n\nĐổi thành viên của một kênh, từ tin nhắn sau. Thay cả danh sách. Thành viên là\nTí hoặc kênh; một kênh trả lời bằng các Tí của nó.\n\nTùy chọn:\n  --chat <mã>      Kênh (bắt buộc)\n  --with <tên>     Một Tí hoặc kênh; lặp lại cho nhiều thành viên\n  --json           In JSON cho máy đọc": "Usage: orglet members --chat <id> --with <name> [--with <name>] [--json]\n\nChanges who is in a channel, from the next message on. Replaces the whole list.\nMembers are orglets or channels; a channel answers as its orglets.\n\nOptions:\n  --chat <id>      The channel (required)\n  --with <name>    An orglet or channel; repeat for more members\n  --json           Print machine-readable JSON",
  "Cách dùng: orglet {0} \"<tin nhắn>\" --with <tên> [--with <tên>] [tùy chọn]\n\nTạo một kênh với các Tí này và gửi tin nhắn đầu tiên, như tạo kênh\ntrong app. Mỗi Tí trả lời lần lượt. Nhắn\ntiếp bằng orglet send --chat <mã>. orglet group là tên cũ của lệnh này.\nVới --space, kênh nằm trong không gian đó; bỏ --with thì kênh nhận mọi Tí\ncủa không gian hoặc của mục. Bỏ tin nhắn và đặt --name thì chỉ tạo kênh.\nKhông có --space, kênh vào không gian dành cho các kênh, tên là Kênh.\n\nTùy chọn:\n  --with <tên>         Một Tí hoặc kênh; lặp lại cho nhiều thành viên\n  --name <tên>         Tên kênh; mặc định là tên các thành viên\n  --topic <chủ đề>     Chủ đề của kênh\n  --space <tên>        Không gian chứa kênh\n  --category <tên>     Mục của không gian đó chứa kênh\n  --file <đường dẫn>   Đính một tệp vào tin nhắn đầu tiên; lặp lại cho nhiều tệp\n  --no-wait            Trả về ngay sau khi gửi\n  --timeout <giây>     Thời gian chờ câu trả lời (mặc định {1})\n  --json               In JSON cho máy đọc": "Usage: orglet {0} \"<message>\" --with <name> [--with <name>] [options]\n\nCreates a channel with these orglets and channels and sends its first message, like\ncreating a channel in the app. Each orglet answers in turn. Keep going with orglet send --chat <id>. orglet group is this command's\nolder name.\nWith --space the channel is in that space; without --with it takes every orglet of\nthe space or of the category. With --name and no message, the channel is only created.\nWithout --space the channel goes to the space kept for channels, named Channels.\n\nOptions:\n  --with <name>        An orglet or channel; repeat for more members\n  --name <name>        The channel's name; the members' names by default\n  --topic <topic>      The channel's topic\n  --space <name>       The space the channel is in\n  --category <name>    The category of that space the channel is in\n  --file <path>        Attach a file to the first message; repeat for more\n  --no-wait            Return right after sending\n  --timeout <seconds>  How long to wait for the answer (default {1})\n  --json               Print machine-readable JSON",
