// British English differs from the US text only in these spellings, so it is derived instead of duplicated.
const british: [RegExp, string][] = [
  [/\b([Ss])ynthesiz/g, '$1ynthesis'], [/\b([Ss])ummariz/g, '$1ummaris'], [/\b([Aa])nalyz/g, '$1nalys'],
  [/\bLicense\b/g, 'Licence'], [/\bcatalog\b/g, 'catalogue'], [/\b([Cc])olor/g, '$1olour'], [/\b([Cc])ustomiz/g, '$1ustomis'],
];
export const enGB: Dictionary = Object.fromEntries(Object.entries(en).map(([key, value]) => [key, british.reduce((text, [pattern, replacement]) => text.replace(pattern, replacement), value)]));
